#!/usr/bin/env python3
from argparse import ArgumentParser
from pathlib import Path
from sys import stderr
from typing import Final

from rowx_postgres._core import TypeInfo, type_table  # ruff: ignore[import-private-name]
from rowx_sqlite._core import TypeInfo as SqliteTypeInfo, type_table as sqlite_type_table  # ruff: ignore[import-private-name]

ROOT: Final[Path] = Path(__file__).resolve().parent.parent
TARGET: Final[Path] = ROOT / "docs" / "types.md"

HEADER: Final[str] = """# Type tables

<!-- generated by scripts/gen-types-doc.py from rowx_postgres._core.type_table() and rowx_sqlite._core.type_table(); do not edit by hand -->

This page is generated from the type tables of the two backends, the single source of truth for the runtime codecs and
for `rowx check`. Regenerate it with `uv run python scripts/gen-types-doc.py`. The rules around the tables are
[Type mapping](reference/type-mapping.md).

## PostgreSQL

The table is in `crates/rowx-postgres/src/types.rs`.

- **Result type** is the Python type a column decodes to, and the leaf your row type must use.
- **Accepted parameters** are the Python types that can be interpolated into a parameter of that type. `None` (SQL
  NULL) is accepted for every parameter.
- **Encoding** is the wire format used to send a parameter.
"""

POSTGRES_NOTES: Final[str] = """
## PostgreSQL notes

- `bool` is never accepted for an integer parameter, and `datetime` is never accepted for a `date` parameter.
- A `float4`/`float8` parameter takes an `int`, but an `int` above 2^53 loses precision.
- `str` is never treated as a sequence, so it cannot be bound to an array parameter.
- `json` and `jsonb` accept any JSON-serialisable value, always encoded with `json.dumps`. A `str` becomes a JSON
  string; to bind raw JSON text, write `{s}::text::jsonb`.
- Timezone rules are checked when encoding: a naive `datetime` for `timestamptz` (or an aware one for `timestamp`)
  raises `EncodeError`.
- A domain behaves as its base type.
- An array column decodes to `list[X]` (nested lists for multi-dimensional arrays). `list[X]` and `list[X | None]`
  both match, at every nesting level.
- Arrays and ranges are always sent in the binary format, whatever the format of their element or subtype is as a
  scalar (a `numeric` parameter is text, a `numeric[]` or `numrange` parameter is binary), so a value can never change
  the element or bound structure.
- `void` decodes to `None` and is only valid as a tuple element.
- A range decodes to `rowx_postgres.Range[T]`, with `T` the leaf of its subtype, in the server's canonical form (`[1,5]`
  of `int4range` is `[1, 6)`). A `None` bound is an infinite side, and `Range(empty=True)` is the empty range. A
  user-defined range over `int4`, `int8`, `numeric`, `date`, `timestamp` or `timestamptz` decodes like the built-in
  range of that subtype and keeps whatever form its own canonical function gives it.
- `interval` decodes to `datetime.timedelta`, which raises `DecodeError` for a month component or ±infinity. Annotating
  the column `rowx_postgres.Interval` reads it losslessly as `months`, `days` and `microseconds` instead, and ±infinity
  keeps the server's sentinel fields (the maximum or minimum of each). A parameter takes either class.
- `money` decodes to `rowx_postgres.Money(minor_units)`, the int8 the server sends. rowx holds no scale, because
  `lc_monetary` can change mid-session; `Money.to_decimal(scale)` takes it explicitly. To read the formatted text, cast
  the column to `text`.
- `bit` and `varbit` decode to a `str` of `0` and `1`. A `bit(n)` parameter of any other length is rejected by the
  server.
- The geometric types decode to frozen dataclasses in `rowx_postgres`: `Point(x, y)`, `Line(a, b, c)`,
  `LineSegment(start, end)`, `Box(upper_right, lower_left)`, `Path(points, closed)`, `Polygon(points)` and
  `Circle(x, y, radius)`, with `points` a tuple of `Point`. The server canonicalises a `box` so its upper right corner
  comes first, and a decoded box shows that order. Equality compares the fields exactly, not with Postgres'
  epsilon-based `~=`, so a NaN coordinate is never equal to anything. A `path` or `polygon` needs at least one point,
  and the server rejects a `line` whose `a` and `b` are both zero.
- `hstore` decodes to `dict[str, str | None]` (a NULL value is `None`; a key is never NULL, and a `None` key in a
  parameter raises `EncodeError`). `ltree` and `lquery` are `str`. `cube` is
  `rowx_postgres.Cube(lower_left, upper_right)`, two `tuple[float, ...]` of one length; the corners keep the order the
  server stores (the first corner written is `lower_left`, not necessarily the minimum), a point has equal corners, and
  the codec sends equal corners as a point. A `str` that the server's parser rejects fails at Bind.
- Extension types (`citext`, `hstore`, `ltree`, `lquery`, `cube`) are recognised by name **and** owning extension, found
  through `pg_depend`, so a same-named type from another schema or no extension is `unsupported-type` in the checker
  and raises `DecodeError` at runtime (when the statement is prepared). The extension may live in any schema.
- Any type not listed here is `unsupported-type` in the checker and raises `DecodeError` at runtime (for example
  multiranges, composites and `xml`).
"""

POSTGRES_DIFFERENCES: Final[str] = """
## Differences from psycopg

Decoding the same server value with rowx and with psycopg gives equal results, except for these cases. A test asserts
that this list matches the one it checks.

- `timestamptz`: rowx always returns a UTC-aware value, while psycopg uses the session `TimeZone`; the instants are
  equal.
- `float4`: rowx widens the exact 32-bit value to a `float`, while psycopg parses the shortest decimal text; the values
  are equal after rounding to 32 bits.
- `char`: A non-ASCII `"char"` is cut to one byte by the server, which is not valid UTF-8, so rowx raises `DecodeError`.
- `interval`: An interval with a month or year part raises `DecodeError` unless the annotation is
  `rowx_postgres.Interval`, while psycopg approximates a month as 30 days.
- `date`: An infinite date raises `DecodeError`, while psycopg raises its own `DataError`.
- `timestamp`: An infinite timestamp raises `DecodeError`, while psycopg raises its own `DataError`.
- `void`: `void` decodes to `None`, while psycopg returns an empty string.
- `inet`: rowx always returns an interface, even for a full-width mask, while psycopg returns an address for `/32` and
  `/128`; the interface's `ip` is that address.
- `int4range`: rowx returns `rowx_postgres.Range`, while psycopg returns its own `Range`; the bounds are equal.
- `int8range`: rowx returns `rowx_postgres.Range`, while psycopg returns its own `Range`; the bounds are equal.
- `numrange`: rowx returns `rowx_postgres.Range`, while psycopg returns its own `Range`; the bounds are equal.
- `daterange`: rowx returns `rowx_postgres.Range`, while psycopg returns its own `Range`; the bounds are equal, but an
  infinite bound of this subtype raises `DecodeError`, while psycopg raises its own `DataError`.
- `tsrange`: rowx returns `rowx_postgres.Range`, while psycopg returns its own `Range`; the bounds are equal, but an
  infinite bound of this subtype raises `DecodeError`, while psycopg raises its own `DataError`.
- `tstzrange`: rowx returns `rowx_postgres.Range`, while psycopg returns its own `Range`; the bounds are equal as
  instants, but an infinite bound of this subtype raises `DecodeError`, while psycopg raises its own `DataError`.
- `money`: rowx returns `rowx_postgres.Money`, the int8 minor units with no scale, while psycopg returns the text the
  server formats under `lc_monetary`.
- `point`: rowx returns `rowx_postgres.Point`, while psycopg returns the text the server formats; the
  coordinates are equal.
- `line`: rowx returns `rowx_postgres.Line`, while psycopg returns the text the server formats; the
  coordinates are equal.
- `lseg`: rowx returns `rowx_postgres.LineSegment`, while psycopg returns the text the server formats; the
  coordinates are equal.
- `box`: rowx returns `rowx_postgres.Box`, while psycopg returns the text the server formats; the
  coordinates are equal.
- `path`: rowx returns `rowx_postgres.Path`, while psycopg returns the text the server formats; the
  coordinates are equal.
- `polygon`: rowx returns `rowx_postgres.Polygon`, while psycopg returns the text the server formats; the
  coordinates are equal.
- `circle`: rowx returns `rowx_postgres.Circle`, while psycopg returns the text the server formats; the
  coordinates are equal.
- `cube`: rowx returns `rowx_postgres.Cube`, while psycopg returns the text the server formats; the coordinates are
  equal.
"""

SQLITE_HEADER: Final[str] = """
## SQLite

The table is in `packages/rowx-sqlite/src/types.rs`, and the lookup from a declared type to a key is in
`crates/rowx-sqlite/src/types.rs`.

- **Declared type** is the column type name in `CREATE TABLE` that selects the key. Names are case-folded, and
  arguments such as `(10, 2)` are ignored.
- **Result type** is the Python type a column decodes to, and the leaf your row type must use.
- **Written from** are the Python types that are bound as that kind. A parameter has no type of its own, so the Python
  type of the value picks the stored form, and `None` (SQL NULL) is accepted everywhere.
- **Stored as** is the SQLite storage class and, for text, the format.
"""

# what each key is declared as and what it is stored as; `render_sqlite` fails when a key of the table has no entry, so a
# new type cannot reach the table undocumented
SQLITE_DECLARED: Final[dict[str, str]] = {
    "integer": "`INTEGER`, or a name containing `INT` (`BIGINT`, `INT8`)",
    "real": "a name containing `REAL`, `FLOA` or `DOUB`",
    "text": "a name containing `CHAR`, `CLOB` or `TEXT`",
    "blob": "a name containing `BLOB`",
    "boolean": "`BOOLEAN`",
    "datetime": "`DATETIME`, `TIMESTAMP`",
    "datetimetz": "`TIMESTAMPTZ`, `DATETIMETZ`",
    "date": "`DATE`",
    "time": "`TIME`",
    "decimal": "`DECIMAL`, `NUMERIC`",
    "uuid": "`UUID`",
    "json": "`JSON`",
    "any": "`ANY`, and any other name",
}
SQLITE_STORED: Final[dict[str, str]] = {
    "integer": "INTEGER",
    "real": "REAL",
    "text": "TEXT",
    "blob": "BLOB",
    "boolean": "INTEGER 0 or 1",
    "datetime": "TEXT `YYYY-MM-DD HH:MM:SS[.ffffff]`, no offset",
    "datetimetz": "TEXT `YYYY-MM-DD HH:MM:SS[.ffffff]+00:00`, UTC",
    "date": "TEXT `YYYY-MM-DD`",
    "time": "TEXT `HH:MM:SS[.ffffff]`",
    "decimal": "TEXT",
    "uuid": "TEXT, lowercase and hyphenated",
    "json": "TEXT, `json.dumps`",
    "any": "by the Python type: INTEGER, REAL, TEXT or BLOB",
}

SQLITE_NOTES: Final[str] = """
## SQLite notes

- A declared type is looked up among the names above first. A name that is not there falls through to SQLite's own
  affinity rules, in SQLite's order: a name containing `INT` is `integer`, then `CHAR`, `CLOB` or `TEXT` is `text`,
  `BLOB` is `blob`, and `REAL`, `FLOA` or `DOUB` is `real`. Any other name is `any`. The substring rules are SQLite's
  and catch names you did not mean: `POINT` and `INTERVAL` contain `INT`, so they are `integer`.
- A column with no declared type, and every expression, takes the storage class the bytecode analysis proves for it
  (`count(*)` is `integer`). Without one it is **untyped**: it reads as `any` by the storage class of each value, and
  the checker accepts any annotation for it ([Checker](reference/checker.md#sqlite)).
- A `STRICT` table allows only `INT`, `INTEGER`, `REAL`, `TEXT`, `BLOB` and `ANY` as column types, so only `integer`,
  `real`, `text`, `blob` and `any` occur there. A date in a strict table is `text`.
- A stored value that disagrees with its column's declared type raises `DecodeError`. It is never converted. A
  `boolean` is the INTEGER 0 or 1 and nothing else.
- `decimal` and `json` columns have numeric affinity in SQLite, which rewrites a stored number: `9.50` reads back as
  `9.5`. A `decimal` is read exactly from TEXT, and from INTEGER or REAL through the shortest text that names the same
  value. A `json` column also reads a stored INTEGER or REAL as the JSON number it spells.
- A naive `datetime` is written as it is and an aware one as UTC. Which of the two a column reads is decided by its
  declared type, so binding a naive value for a `TIMESTAMPTZ` column is `DecodeError` when it is read back, not an
  `EncodeError` when it is written.
- A Python `int` outside the 64-bit range, a `float` that is NaN, a `str` with a NUL or a lone surrogate, and an aware
  `time` are `EncodeError`. A type with no row above is `EncodeError`. A `dict`, `list` or `tuple` is bound as JSON
  text with `allow_nan=False`.
- JSON in a `BLOB` (SQLite's `JSONB`) raises `DecodeError`. Store JSON as TEXT.
"""

TZ_LABELS: Final[dict[str, str]] = {"none": "", "aware": "aware", "naive": "naive"}


def _cell(text: str) -> str:
    return text.replace("|", "\\|")


def _code_list(items: list[str]) -> str:
    return ", ".join(f"`{item}`" for item in items) if items else "none"


def _row(info: TypeInfo) -> str:
    result = f"`{info.py_result}`" if info.py_result else "base type"
    if info.alt_py_results:
        result += "; or " + _code_list(list(info.alt_py_results)) + " by annotation"
    accepted = _code_list(info.accepted_params)
    encoding = info.encode_format
    match info.key:
        case "array":
            result, encoding = "`list[X]`", "binary"
        case "json" | "jsonb":
            result, accepted = "any value (`json.loads`)", "any JSON-serialisable value"
        case "domain":
            accepted, encoding = "base type", "base type"
        case "void":
            encoding = ""
        case key if key.endswith("range"):
            encoding = "binary"
    cells = (
        f"`{info.key}`",
        result,
        TZ_LABELS[info.tz],
        accepted,
        encoding,
    )
    return "| " + " | ".join(_cell(c) for c in cells) + " |"


def _sqlite_row(info: SqliteTypeInfo) -> str:
    cells = (
        f"`{info.key}`",
        SQLITE_DECLARED[info.key],
        f"`{info.py_result}`",
        TZ_LABELS[info.tz],
        _code_list(info.accepted_params),
        SQLITE_STORED[info.key],
    )
    return "| " + " | ".join(_cell(c) for c in cells) + " |"


def render_sqlite() -> str:
    table = sqlite_type_table()
    keys = {info.key for info in table}
    if keys != SQLITE_DECLARED.keys() or keys != SQLITE_STORED.keys():
        print("the SQLite type table and the generator's declared and stored text disagree", file=stderr)  # ruff: ignore[print]
        raise SystemExit(1)
    lines = [
        "| Type key | Declared type | Result type | Timezone | Written from | Stored as |",
        "|---|---|---|---|---|---|",
        *(_sqlite_row(info) for info in table),
    ]
    return SQLITE_HEADER + "\n" + "\n".join(lines) + "\n" + SQLITE_NOTES


def render() -> str:
    lines = [
        "| Type key | Result type | Timezone | Accepted parameters | Encoding |",
        "|---|---|---|---|---|",
        *(_row(info) for info in type_table()),
    ]
    return HEADER + "\n" + "\n".join(lines) + "\n" + POSTGRES_NOTES + POSTGRES_DIFFERENCES + render_sqlite()


def main() -> int:
    parser = ArgumentParser(description="Generate docs/types.md from the rowx type tables.")
    parser.add_argument("--check", action="store_true", help="exit 1 if docs/types.md is out of date")
    args = parser.parse_args()

    expected = render()
    if args.check:
        if not TARGET.exists() or TARGET.read_text(encoding="utf-8") != expected:
            print(f"{TARGET.relative_to(ROOT)} is out of date; run scripts/gen-types-doc.py", file=stderr)  # ruff: ignore[print]
            return 1
        return 0
    TARGET.write_text(expected, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
